            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "And we are put on earth a little space, That we may learn to bear the beams of love, And these black bodies and this sunburnt face Is but a cloud, and like a shady grove.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "I'll shade him from the heat till he can bear To lean in joy upon our Father's knee; And then I'll stand and stroke his silver hair, And be like him and he will then love me.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "When my mother died I was very young, And my father sold me while yet my tongue Could scarcely cry 'weep! 'weep! 'weep! 'weep! So your chimneys I sweep, and in soot I sleep.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "To Mercy, Pity, Peace, and Love All pray in their distress; And to these virtues of delight Return their thankfulness.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "For Mercy, Pity, Peace, and Love Is God, our father dear, And Mercy, Pity, Peace, and Love Is Man, his child and care.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "For Mercy has a human heart, Pity a human face, And Love, the human form divine, And Peace, the human dress.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Then every man, of every clime, That prays in his distress, Prays to the human form divine, Love, Mercy, Pity, Peace. And all must love the human form, In heathen, Turk, or Jew; Where Mercy, Love, and Pity dwell There God is dwelling too.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "The moon like a flower In heaven's high bower, With silent delight, Sits and smiles on the night.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "And there the lion's ruddy eyes Shall flow with tears of gold, And pitying the tender cries, And walking round the fold, Saying: \"Wrath by his meekness, And by his health, sickness, Is driven away From our immortal day.\"", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "\"For washed in life's river, My bright mane forever Shall shine like the gold As Iguard o'er the fold.\"", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "When the voices of children are heard on the green And laughing is heard on the hill, My heart is at rest within my breast And everything else is still.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Can I see another's woe, And not be in sorrow too? Can I see another's grief, And not seek for kind relief?", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Nothing can be more contemptible than to suppose Public Records to be True.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Degrade first the arts if you'd mankind degrade, Hire idiots to paint with cold light and hot shade.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "To Generalize is to be an Idiot. To Particularize is the Alone Distinction of Merit - General Knowledges are those Knowledges that Idiots possess.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "The Foundation of Empire is Art and Science Remove them or Degrade them and the Empire is No More - Empire follows Art and Not Vice Versa as Englishmen suppose.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Without contraries there is no progression. Attraction and repulsion, reason and energy, love and hate are necessary to human existence.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Those who restrain desire do so because theirs is weak enough to be restrained; and the restrainer or reason usurps its place and governs the unwilling.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "If the doors of perception were cleansed, everything would appear to man as it is: infinite.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "The man who never alters his opinion is like standing water, and breeds reptiles of the mind.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Opposition is true Friendship.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "The road of excess leads to the palace of wisdom.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "He who desires but acts not breeds pestilence.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "A fool sees not the same tree that a wise man sees. He whose face gives no light shall never become a star.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Eternity is in love with the productions of time.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "The busy bee has no time for sorrow.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "The hours of folly are measur'd by the clock, but of wisdom no clock can measure.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "All wholesome food is caught without a net or a trap.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "No bird soars too high if he soars with his own wings.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "If the fool would persist in his folly he would become wise.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Prisons are built with stones of law; brothels with bricks of religion.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "The pride of the peacock is the glory of God. The lust of the goat is the bounty of God. The wrath of the lion is the wisdom of God. The nakedness of woman is the work of God.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "The cistern contains: the fountain overflows.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "One thought fills immensity.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Always be ready to speak your mind, and a base man will avoid you.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "The eagle never lost so much time as when he submitted to learn of the crow.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Think in the morning. Act in the noon. Eat in the evening. Sleep in the night.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "The tygers of wrath are wiser than the horses of instruction.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "You never know what is enough unless you know what is more than enough.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "The weak in courage is strong in cunning.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "When thou seest an Eagle, thou seest a portion of Genius; lift up thy head!", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Exuberance is Beauty.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Improvement makes straight roads; but the crooked roads without improvement are roads of genius.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Truth can never be told so as to be understood, and not be believed.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Enough! or too much.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Never seek to tell thy love Love that never told can be; For the gentle wind does move Silently, invisibly.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "I told my love, I told my love, I told her all my heart; Trembling, cold, in ghastly fears- Ah, she doth depart.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Soon as she was gone from me A traveler came by Silently, invisibly- Oh, was no deny.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "I asked a thief to steal me a peach: He turned up his eyes. I asked a lithe lady to lie her down: Holy and meek, she cries.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "As soon as I went An angel came. He winked at the thief And smiled at the dame- And without one word said Had a peach from the tree, And still as a maid Enjoyed the lady.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Sleep, sleep, beauty bright, Dreaming o'er the joys of night. Sleep, sleep: in thy sleep Little sorrows sit and weep.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Why art thou silent and invisible, Father of Jealousy?", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Love to faults is always blind, Always is to joys inclined, Lawless, winged, and unconfined, And breaks all chains from every mind.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "The sword sung on the barren heath, The sickle in the fruitful field; The sword he sung a song of death, But could not make the sickle yield.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Abstinence sows sand all over The ruddy limbs and flaming hair, But desire gratified Plants fruits of life and beauty there.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "If you trap the moment before it's ripe, The tears of repentance you'll certainly wipe; But if once you let the ripe moment go You can never wipe off the tears of woe.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "The look of love alarms Because 'tis filled with fire; But the look of soft deceit Shall win the lover's hire.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "What is it men in women do require? The lineaments of gratified desire. What is it women do in men require? The lineaments of gratified desire.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "You'll quite remove the ancient curse.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Hear the voice of the Bard, Who present, past, and future, sees; Whose ears have heard The Holy Word That walked among the ancient trees.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Turn away no more; Why wilt thou turn away? The starry floor, The watery shore Is given thee till the break of day.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "O Rose thou art sick. The invisible worm, That flying flies in the night In the howling storm: Has found out thy bed Of crimson joy: And his dark secret love Does thy life destroy.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "The modest Rose puts forth a thorn, The humble sheep a threat'ning horn: While the Lily white shall in love delight, Nor a thorn nor a threat stain her beauty bright.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "In every cry of every Man, In every Infant's cry of fear, In every voice, in every ban, The mind-forg'd manacles I hear.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "But most, thro' midnight streets I hear How the youthful Harlot's curse Blasts the new born Infant's tear, And blights with plagues the Marriage hearse.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Pity would be no more If we did not make somebody Poor; And Mercy no more could be If all were as happy as we.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "My mother groan'd! my father wept. Into the dangerous world I leapt: Helpless, naked, piping loud: Like a fiend hid in a cloud.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "I was angry with my friend: I told my wrath, my wrath did end. I was angry with my foe: I told it not, my wrath did grow.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "In the morning glad I see My foe outstretch'd beneath the tree.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Children of the Future Age Reading this indignant page, Know that in a former time Love! sweet Love! was thought a crime.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Cruelty has a human heart, And Jealousy a human face; Terror the human form divine, And Secrecy the human dress.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Tyger! Tyger! burning bright in the forests of the night, What immortal hand or eye Could frame thy fearful symmetry?", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "In what distant deeps or skies Burnt the fire of thine eyes? On what wings dare he aspire? What the hand dare seize the fire?", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "When the stars threw down their spears, And water'd heaven with their tears, Did he smile his work to see? Did he who made the Lamb make thee?", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "What is Grand is necessarily obscure to Weak men. That which can be made Explicit to the idiot is not worth my care.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Fun I love, but too much Fun is of all things the most loathsom. Mirth is better than Fun and Happiness is better than Mirth.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "But to the Eyes of the Man of Imagination, Nature is Imagination itself. As a man is, So he Sees. As the Eye is formed, such are its Powers.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "When a Man has Married a Wife He finds out whether Her Knees and elbows are only glued together.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Art can never exist without Naked Beauty displayed.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Art is the tree of life. SCIENCE is the Tree of DEATH ART is the Tree of LIFE GOD is JESUS", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Jesus and his apostles and disciples were all artists", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "To see a World in a Grain of Sand And a Heaven in a Wild Flower, Hold Infinity in the palm of your hand And Eternity in an hour.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "A robin redbreast in a cage Puts all Heaven in a rage.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "A dog starved at his master's gate Predicts the ruin of the state.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "He who shall hurt the little wren Shall never be beloved by men.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "A truth that's told with bad intent Beats all the lies you can invent.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Man was made for joy and woe, And when this we rightly know Through the world we safely go. Joy and woe are woven fine, A clothing for the soul divine.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Every tear from every eye Becomes a babe in eternity.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "He who shall teach the child to doubt The rotting grave shall ne'er get out.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "The strongest poison ever known Came from Caesar's laurel crown.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "He who doubts from what he sees Will ne'er believe, do what you please. If the sun and moon should doubt They'd immediately go out.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "The harlot's cry from street to street Shall weave old England's winding sheet.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Every night, and every morn, Some to misery are born. Every morn, and every night, Some are born to sweet delight. Some are born to sweet delight. Some are born to endless night.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "God appears and god is light To those poor souls who dwell in night But does a human form display To those who dwell in realms of day", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "My specter around me night and day Like a wild beast guards my way, My emanation far within Weeps incessantly for my sin.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "And throughout all eternity I forgive you, you forgive me.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Mock on, mock on, Voltaire, Rousseau. Mock on, mock on - 'tis all in vain! You throw the sand against the wind, And the wind blows it back again.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Terror in the house does roar, But Pity stands before the door.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "There is a smile of love, And there is a smile of deceit, And there is a smile of smiles In which these two smiles meet.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "This cabinet is formed of gold And pearl and crystal shining bright, And within it opens into a world And a little lovely moony night.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "For a tear is an intellectual thing, And a sigh is the sword of an Angel King, And the bitter groan of the martyr's woe Is an arrow from the Almighty's bow.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "The Stolen and Perverted Writings of Homer and Ovid, of Plato and Cicero, which all men ought to contemn, are set up by artifice against the Sublime of the Bible", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Rouze up, O Young Men of the New Age! set your foreheads against the ignorant Hirelings! For we have Hirelings in the Camp, the Court and the University, who would, if they could, for ever depress Mental and prolong Corporeal War.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "And did those feet in ancient time, Walk upon England's mountains green? And was the holy Lamb of God On England's pleasant pastures seen? And did the Countenance Divine Shine forth upon our clouded hills? And was Jerusalem builded here Among these dark Satanic mills?", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Bring me my Bow of burning gold, Bring me my Arrows of desire, Bring me my Spear - O clouds, unfold! Bring me my Chariot of fire!", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "I will not cease from mental fight, Nor shall my sword sleep in my hand, Till we have built Jerusalem In England's green and pleasant land.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Time is the mercy of Eternity; without Time's swiftness Which is the swiftest of all things, all were eternal torment.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Great things are done when men and mountains meet; This is not done by jostling in the street.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "If you have formed a circle to go into, Go into it yourself and see how you would do.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "The Angel that presided o'er my birth Said, \"Little creature, formed of joy and mirth, Go love without the help of any thing on earth.\"", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Half Friendship is the bitterest Enmity...", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Every Thing has its Vermin O Spectre of the Sleeping Dead!", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Poetry Fetter'd. Fetters the Human Race. Nations are Destroy'd, or Flourish, in proportion as Their Poetry, Painting, and Music are Destroy'd or Flourish!", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Trembling I sit day and night, my friends are astonish'd at me. Yet they forgive my wanderings, I rest not from my great task! To open the Eternal Worlds, to open the immortal Eyes Of Man inwards into the Worlds of Thought: into Eternity Ever expanding in the Bosom of God. the Human Imagination", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "O Saviour pour upon me thy Spirit of meekness and love: Annihilate the Selfhood in me, be thou all my life! Guide thou my hand which trembles exceedingly upon the rock of ages", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "They have divided themselves by Wrath. they must be united by Pity", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Pity must join together those whom wrath has torn in sunder", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "I must Create a System, or be enslav'd by another Man's; I will not Reason and Compare: my business is to Create.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "For every thing exists and not one sigh nor smile nor tear, One hair nor particle of dust, not one can pass away.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "I see the Four-fold Man. The Humanity in deadly sleep, And its fallen Emanation. The Spectre and its cruel Shadow. I see the Past, Present and Future, existing all at once Before me; O Divine Spirit sustain me on thy wings!", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "SUCH VISIONS HAVE APPEARD TO ME AS I MY ORDERD RACE HAVE RUN JERUSALEM IS NAMED LIBERTY AMONG THE SONS OF ALBION", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "The fields from Islington to Marybone, To Primrose Hill and Saint John's Wood: Were builded over with pillars of gold, And there Jerusalems pillars stood.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Pancrass and Kentish-town repose Among her golden pillars high: Among her golden arches which Shine upon the starry sky.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "He who would do good to another must do it in minute particulars; General good is the plea of the scoundrel, hypocrite, and flatterer: For art and science cannot exist but in minutely organized Particulars.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "What is a Wife and what is a Harlot? What is a Church and What Is a Theatre? are they Two and not One? can they Exist Separate? Are not Religion and Politics the Same Thing? Brotherhood is Religion O Demonstrations of Reason Dividing Families in Cruelty and Pride!", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "England! awake! awake! awake! Jerusalem thy sister calls! Why wilt thou sleep the sleep of death And close her from thy ancient walls?", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Commerce is so far from being beneficial to Arts or to Empire, that it is destructive of both, as all their History shows, for the above Reason of Individual Merit being its Great Hatred. Empires flourish till they become Commercial and then they are scattered abroad to the four winds", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "When I tell any Truth it is not for the sake of Convincing those who do not know it but for the sake of defending those who Do", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Every Harlot was a Virgin once", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "It is not because Angels are Holier than Men or Devils that makes them Angels but because they do not Expect Holiness from one another but from God only", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "Thinking as I do that the Creator of this World is a very Cruel Being and being a Worshipper of Christ, I cannot help saying: \"the Son, O how unlike the Father!\" First God Almighty comes with a Thump on the Head. Then Jesus Christ comes with a balm to heal it.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "This world of imagination is the world of eternity.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "You cannot have Liberty in this world without what you call Moral Virtue and you cannot have Moral Virtue without the Slavery of that half of the Human Race who hate what you call Moral Virtue", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "...some say that Happiness is not Good for Mortals and they ought to be answerd that Sorrow is not fit for Immortals and is utterly useless to any one a blight never does good to a tree and if a blight kill not a tree but it still bear fruit let none say that the fruit was in consequence of the blight.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "The Goddess Fortune is the devils servant ready to Kiss any ones Arse.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "This life's dim windows of the soul Distorts the heavens from pole to pole And leads you to believe a lie When you see with, not through, the eye.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "\"I die, I die!\" the Mother said, \"My children die for lack of Bread.\"", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "My Brother starv'd between two Walls, His Children's Cry my Soul appalls;", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "The iron hand crush'd the Tyrant's head And became a Tyrant in his stead.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "When a sinister person means to be your enemy, they always start by trying to become your friend.", Author = "William Blake" },
            new Quote { Id = "https://en.wikiquote.org/wiki/William_Blake", Text = "I myself do nothing. The Holy Spirit accomplishes all through me.", Author = "William Blake" },
        };
    }
}